/**
 * The default @class of every element of the bundled OASIS document types, as a compact table
 * for the language server (`server/src/data/ditaClasses.ts`, generated by
 * `scripts/generate-dita-classes.js`).
 *
 * The server decides by class whether a content reference may reuse an element: the referenced
 * element must be the referencing element or a specialization of it (DITA 1.3 §2.4.2.2,
 * §3.12.13.7). It has no grammar of its own at run time, so it reads this table. The table is
 * built from the same compiled grammars as the visual preview, and a test checks that the
 * generated file matches them.
 *
 * Shape: the DITA 1.3 classes, as in a topic document, are the base. The overrides give the
 * classes that differ by DITA version ("1.2", "2.0") and by document type ("1.3/map": three
 * elements, such as `shortdesc`, have one class in maps and another in topics). Elements are
 * looked up as `overrides["<version>/map"] ?? overrides["<version>"] ?? base`.
 *
 * Environment-neutral.
 */

import { classTokens } from './classTokens';
import type { Grammar } from './types';

export type ClassVersion = '1.2' | '1.3' | '2.0';

export interface ClassTable {
    /** Element name → class (single spaces, no trailing space), DITA 1.3, topic documents first. */
    base: Record<string, string>;
    /** "1.2", "2.0", "1.2/map", "1.3/map", "2.0/map" → element name → class, where it differs. */
    overrides: Record<string, Record<string, string>>;
}

const VERSIONS: ClassVersion[] = ['1.2', '1.3', '2.0'];

/** A class value as the table stores it: tokens separated by single spaces, no trailing space. */
export function normalizeClass(value: string): string {
    return value.trim().split(/\s+/).join(' ');
}

/** Whether a grammar is a map document type: one of its roots is a `map/map`. */
function isMapGrammar(grammar: Grammar): boolean {
    return grammar.roots.some((root) => classTokens(grammar.elements[root]?.class).includes('map/map'));
}

/**
 * Build the table from compiled grammars. Throws when one element has two classes in the same
 * DITA version and document type, which the table cannot represent.
 */
export function buildClassTable(grammars: readonly Grammar[]): ClassTable {
    // version → context → element → class
    const classes = new Map<string, Map<string, string>>();
    const at = (version: string, context: 'topic' | 'map'): Map<string, string> => {
        const key = `${version}/${context}`;
        let found = classes.get(key);
        if (!found) {
            found = new Map();
            classes.set(key, found);
        }
        return found;
    };
    for (const grammar of grammars) {
        if (!(VERSIONS as string[]).includes(grammar.ditaVersion)) {
            continue;
        }
        const table = at(grammar.ditaVersion, isMapGrammar(grammar) ? 'map' : 'topic');
        for (const [name, element] of Object.entries(grammar.elements)) {
            if (!element.class) {
                continue; // foreign vocabulary (MathML, SVG)
            }
            const value = normalizeClass(element.class);
            const previous = table.get(name);
            if (previous !== undefined && previous !== value) {
                throw new Error(`<${name}> has two classes in DITA ${grammar.ditaVersion} (${grammar.id}): "${previous}" and "${value}"`);
            }
            table.set(name, value);
        }
    }

    const base: Record<string, string> = {};
    for (const context of ['topic', 'map'] as const) {
        for (const [name, value] of at('1.3', context)) {
            base[name] ??= value;
        }
    }
    const overrides: Record<string, Record<string, string>> = {};
    const set = (key: string, name: string, value: string): void => {
        (overrides[key] ??= {})[name] = value;
    };
    for (const version of VERSIONS) {
        // The version's own classes: from topic documents first, as for the base
        const own = new Map<string, string>();
        for (const context of ['topic', 'map'] as const) {
            for (const [name, value] of at(version, context)) {
                if (!own.has(name)) {
                    own.set(name, value);
                }
            }
        }
        for (const [name, value] of own) {
            if (base[name] !== value) {
                set(version, name, value);
            }
        }
        for (const [name, value] of at(version, 'map')) {
            if ((overrides[version]?.[name] ?? base[name]) !== value) {
                set(`${version}/map`, name, value);
            }
        }
    }
    return { base, overrides };
}

/** The source of `server/src/data/ditaClasses.ts`: sorted, so that a regenerated table diffs cleanly. */
export function renderClassTable(table: ClassTable): string {
    const record = (entries: Record<string, string>, indent: string): string => Object.keys(entries).sort()
        .map((name) => `${indent}${JSON.stringify(name)}: ${JSON.stringify(entries[name])},`).join('\n');
    const overrides = Object.keys(table.overrides).sort()
        .map((key) => `    ${JSON.stringify(key)}: {\n${record(table.overrides[key], '        ')}\n    },`).join('\n');
    return [
        '/**',
        ' * The default @class of the elements of the OASIS DITA document types (1.2, 1.3, 2.0).',
        ' *',
        ' * GENERATED by `scripts/generate-dita-classes.js` from the grammars compiled from `dtds/`',
        ' * (`src/shared/grammar/classTable.ts`): do not edit. `npm run test:shared` checks that it',
        ' * matches the grammars.',
        ' *',
        ' * `BASE_CLASSES` are the DITA 1.3 classes, as in a topic document. `CLASS_OVERRIDES` give',
        ' * the classes that differ by DITA version ("1.2", "2.0") and in maps ("1.3/map"…): an',
        ' * element is looked up as overrides["<version>/map"] ?? overrides["<version>"] ?? base.',
        ' */',
        '',
        'export const BASE_CLASSES: Readonly<Record<string, string>> = {',
        record(table.base, '    '),
        '};',
        '',
        'export const CLASS_OVERRIDES: Readonly<Record<string, Readonly<Record<string, string>>>> = {',
        overrides,
        '};',
        '',
    ].join('\n');
}
